def habilidades():
    out = []
    for linha in HABILIDADES.strip().splitlines():
        c, eixo, objeto, texto = linha.split('|')
        out.append({'codigo': c, 'ano': 1 if c.startswith('EF15') else 6, 'eixo': eixo, 'objeto': objeto, 'texto': texto, 'recursos': []})
